struct State { n: i32, data: i32[] }
function consume(own value: State): i32 { return value.n + value.data.len(); }
function take(own value: State): State { return value; }
function drain(own value: i32[]): i32 { return value.len(); }
function work(own state: State, choose: boolean): i32 { let State { n, data } = state; match (choose) { true => { let state = State { n: n + 1, data: data }; return consume(state); }, false => { return n + data.len(); } } }

